const previo = $('When Executed by Another Workflow').first().json;
const mensaje = previo.mensaje;

const meses = { enero:'01', febrero:'02', marzo:'03', abril:'04', mayo:'05', junio:'06', julio:'07', agosto:'08', septiembre:'09', octubre:'10', noviembre:'11', diciembre:'12' };

function resolverAnio(mes, dia, anioExplicito) {
  if (anioExplicito) return anioExplicito;
  const hoy = new Date();
  let anio = hoy.getFullYear();
  const candidata = new Date(`${anio}-${mes}-${dia}`);
  if (candidata < hoy) anio += 1;
  return String(anio);
}

const patronMeses = 'enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre';
const matchRango = mensaje.match(new RegExp('del\\s+(\\d{1,2})\\s+al\\s+(\\d{1,2})\\s+de\\s+(' + patronMeses + ')(?:\\s+de\\s+(\\d{4}))?', 'i'));
const matchUnica = mensaje.match(new RegExp('(\\d{1,2})\\s+de\\s+(' + patronMeses + ')(?:\\s+de\\s+(\\d{4}))?', 'i'));

let fecha_inicio = '', fecha_fin = '';

if (matchRango) {
  const dia1 = matchRango[1].padStart(2, '0');
  const dia2 = matchRango[2].padStart(2, '0');
  const mes = meses[matchRango[3].toLowerCase()];
  const anio = resolverAnio(mes, dia1, matchRango[4]);
  fecha_inicio = `${anio}-${mes}-${dia1}`;
  fecha_fin = `${anio}-${mes}-${dia2}`;
} else if (matchUnica) {
  const dia = matchUnica[1].padStart(2, '0');
  const mes = meses[matchUnica[2].toLowerCase()];
  const anio = resolverAnio(mes, dia, matchUnica[3]);
  fecha_inicio = fecha_fin = `${anio}-${mes}-${dia}`;
}

const rango = fecha_inicio === fecha_fin ? fecha_inicio : (fecha_inicio + ' al ' + fecha_fin);

let titulo = mensaje;
if (matchRango) titulo = titulo.replace(matchRango[0], '');
else if (matchUnica) titulo = titulo.replace(matchUnica[0], '');
titulo = titulo.replace(/\b(apunta(lo)?|agendame|agenda|pon en el calendario que|pon en el calendario|crea un evento|a(n|ñ)ade|anota|recuerdame)\b/gi, '');
titulo = titulo.replace(/^[\s,:.;-]+|[\s,:.;-]+$/g, '').trim();
titulo = titulo.replace(/^(para|de|el|la|que)\s+/i, '').trim();
if (!titulo) titulo = 'Recordatorio';
titulo = titulo.charAt(0).toUpperCase() + titulo.slice(1);

return [{ json: { usuario_id: previo.usuario_id, chat_id: previo.chat_id, categoria: 'recordatorio', contenido: rango + ': ' + titulo, fecha_inicio, fecha_fin, titulo, rango } }];

